import { describe, it, expect } from 'vitest'
import { render } from '@testing-library/svelte'
import { createRawSnippet, type Component } from 'svelte'
import * as pkg from '../../src/index.js'
import fixture from '../fixtures/contract.json'
import { CASES } from './cases.js'
import { canonical, fromHtml } from './canonical.js'
import { DIVERGENCES, NO_SSR_CONTRACT } from './divergences.js'

/* Every Svelte component must render the same DOM tree as its React
 * counterpart, for every case in cases.ts. React's side is server HTML
 * generated by scripts/generate-contract-fixtures.tsx; `test:contract-fresh`
 * fails if it goes stale. Components are looked up from the package's own
 * exports, so what is tested is what ships. */

type Fixture = { version: number; components: Record<string, Record<string, { props: unknown; html: string }>> }
const f = fixture as Fixture

function hydrate(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(hydrate)
  if (value && typeof value === 'object') {
    const v = value as Record<string, unknown>
    if ('$el' in v) {
      const text = String(v.$el).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]!)
      return createRawSnippet(() => ({ render: () => `<b>${text}</b>` }))
    }
    if ('$fn' in v) return () => {}
    return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, hydrate(x)]))
  }
  return value
}

const exported = Object.entries(pkg)
  .filter(([name, v]) => /^[A-Z]/.test(name) && typeof v === 'function')
  .map(([name]) => name)
  .sort()

describe('React DOM contract', () => {
  it('uses the v2 full-tree fixture', () => {
    expect(f.version).toBe(2)
  })

  // The fixture and the case file must agree, or the fixture is stale.
  it('fixture covers exactly the cases in cases.ts', () => {
    const fromCases = Object.fromEntries(Object.entries(CASES).map(([n, c]) => [n, Object.keys(c).sort()]))
    const fromFixture = Object.fromEntries(Object.entries(f.components).map(([n, c]) => [n, Object.keys(c).sort()]))
    expect(fromFixture).toEqual(fromCases)
  })

  // Denominator: every shipped component is contract-tested or excused by name.
  it('every exported component is in the contract or explicitly excused', () => {
    const uncovered = exported.filter(n => !(n in f.components) && !(n in NO_SSR_CONTRACT))
    expect(uncovered).toEqual([])
    const stale = Object.keys(NO_SSR_CONTRACT).filter(n => n in f.components || !exported.includes(n))
    expect(stale).toEqual([])
  })

  for (const [name, cases] of Object.entries(f.components)) {
    describe(name, () => {
      it('is exported by the package', () => {
        expect(exported).toContain(name)
      })

      for (const [caseName, { props, html }] of Object.entries(cases)) {
        it(caseName, () => {
          const Comp = (pkg as Record<string, unknown>)[name] as Component<any>
          const { container } = render(Comp, { props: hydrate(props) as Record<string, unknown> })
          for (const d of DIVERGENCES[name] ?? []) d.apply(container)
          expect(canonical(container)).toBe(canonical(fromHtml(html)))
        })
      }
    })
  }
})
